package com.dy.artisan3d.utilimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_conflictimport artisan3d.composeapp.generated.resources.error_no_internetimport artisan3d.composeapp.generated.resources.error_payload_too_largeimport artisan3d.composeapp.generated.resources.error_request_timeoutimport artisan3d.composeapp.generated.resources.error_serializationimport artisan3d.composeapp.generated.resources.error_server_errorimport artisan3d.composeapp.generated.resources.error_too_many_requestsimport artisan3d.composeapp.generated.resources.error_unauthorizedimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.domain.model.NetworkErrorimport org.jetbrains.compose.resources.StringResource// NetworkError.ktfun NetworkError.toErrorMessage(): StringResource {    return when (this) {        is NetworkError.RequestTimeout -> Res.string.error_request_timeout        is NetworkError.Unauthorized -> Res.string.error_unauthorized        is NetworkError.Conflict -> Res.string.error_conflict        is NetworkError.TooManyRequests -> Res.string.error_too_many_requests        is NetworkError.NoInternet -> Res.string.error_no_internet        is NetworkError.PayloadTooLarge -> Res.string.error_payload_too_large        is NetworkError.ServerError -> Res.string.error_server_error        is NetworkError.Serialization -> Res.string.error_serialization        is NetworkError.Unknown -> Res.string.error_unknown    }}